package com.acttub.actingapi.schema;
import static org.assertj.core.api.Assertions.*; import java.util.*; import com.acttub.actingapi.support.PostgresContainerSupport; import org.junit.jupiter.api.Test; import org.flywaydb.core.Flyway; import java.sql.*;
class TimestampPolicyIT {@Test void transactionClockNeverMakesUpdatedAtOlderThanCreatedAt()throws Exception{String url=PostgresContainerSupport.createDatabase("timestamp_policy");Flyway.configure().dataSource(url,PostgresContainerSupport.POSTGRES.getUsername(),PostgresContainerSupport.POSTGRES.getPassword()).load().migrate();try(Connection c=DriverManager.getConnection(url,PostgresContainerSupport.POSTGRES.getUsername(),PostgresContainerSupport.POSTGRES.getPassword());PreparedStatement p=c.prepareStatement("INSERT INTO users(id,status) VALUES (?,'active'::user_status_t) RETURNING created_at,updated_at")){p.setObject(1,UUID.randomUUID());try(ResultSet rs=p.executeQuery()){rs.next();assertThat(rs.getObject(2,java.time.OffsetDateTime.class)).isAfterOrEqualTo(rs.getObject(1,java.time.OffsetDateTime.class));}}}}
